use serde::Serialize;

use crate::client::PushError;

pub struct Client {
    pub base_url: String,
    pub api_key: String,
}

#[derive(Serialize)]
pub struct Order {
    pub id: u64,
    pub total: u64,
}

pub async fn sync_orders(client: &Client, orders: Vec<Order>) -> Result<usize, PushError> {
    println!("sync start: {} orders", orders.len());
    let mut sent = 0;
    for order in &orders {
        println!("sending order {}", order.id);
        match client.push(order).await {
            Ok(()) => sent += 1,
            Err(error) => println!("push failed for order {}: {}", order.id, error),
        }
    }
    println!("sync done: {} sent", sent);
    Ok(sent)
}

