use serde::Serialize;
use tracing::{debug, info, instrument, warn};

use crate::client::PushError;

#[derive(Debug)]
pub struct Client {
    pub base_url: String,
    pub api_key: String,
}

#[derive(Debug, Serialize)]
pub struct Order {
    pub id: u64,
    pub total: u64,
}

#[instrument]
pub async fn sync_orders(client: &Client, orders: Vec<Order>) -> Result<usize, PushError> {
    info!(count = orders.len(), "sync start");
    let mut sent = 0;
    for order in &orders {
        debug!(order_id = order.id, "sending");
        match client.push(order).await {
            Ok(()) => sent += 1,
            Err(error) => warn!(order_id = order.id, %error, "push failed"),
        }
    }
    info!(sent, "sync done");
    Ok(sent)
}

use tracing::{debug, info, info_span, instrument, warn, Instrument};

for order in &orders {
    let span = info_span!("push", order_id = order.id);
    async {
        debug!("sending");
        match client.push(order).await {
            Ok(()) => sent += 1,
            Err(error) => warn!(%error, "push failed"),
        }
    }
    .instrument(span)
    .await;
}
